Where-Object {
      $candidate = $_
      $title = [string]$candidate.MainWindowTitle
      if ([string]::IsNullOrWhiteSpace($title)) { return $false }
      if ($CRP -and ($title -like "*$CRP*" -or $title -like "*$($CRP.Replace('-', '_'))*")) {
        return $true
      }
      return ($title -like "*$RepositoryName*" -and ($title -like '*<-->*' -or $title -like '*Review*' -or $title -like '*Beyond Compare*'))
    }

Add-Member -NotePropertyName 'state_reason' -NotePropertyValue $(if ($hasConcreteChanges) {
        'Reinstated with concrete correction requests; implementation, verification, and exact-identity BCR are required.'
    } else {
        'Reinstated without concrete correction requests; awaiting revised proposal intent and plan approval.'
    }) -Force

Add-Member -NotePropertyName 'bcr_audit' -NotePropertyValue @(
                [PSCustomObject]@{
                    disposition = 'Completed'
                    timestamp = $timestamp
                    cohort_id = $CohortId
                    resolution_receipt = $ResolutionReceiptPath
                    review_receipt = $reviewReceiptPath
                    note = $Details
                }
            ) -Force

ForEach-Object {
        [pscustomobject]@{
          Id = [int]$_.id
          Repository = ConvertTo-WorkspacePushRepositoryName -RepositoryName $_.origin_repo
          BundlePath = Resolve-WorkspaceProposalBundlePath -Proposal $_ -RepositoryName $_.origin_repo
        }
      }

ForEach-Object {
        $props = Get-ItemProperty -Path $_.PSPath -ErrorAction SilentlyContinue
        if ($props.DriverDesc -like "*Intel*" -or $props.DriverDesc -like "*Ethernet*") {
            Write-Host "  --> Disabling WoL/Pattern wake on: $($props.DriverDesc)" -ForegroundColor Green
            Set-ItemProperty -Path $_.PSPath -Name "*WakeOnPattern" -Value "0" -Type String -Force -ErrorAction SilentlyContinue
            Set-ItemProperty -Path $_.PSPath -Name "*WakeOnMagicPacket" -Value "0" -Type String -Force -ErrorAction SilentlyContinue
            Set-ItemProperty -Path $_.PSPath -Name "WakeOnMagicPacketFromS5" -Value "0" -Type String -Force -ErrorAction SilentlyContinue
            Set-ItemProperty -Path $_.PSPath -Name "EnablePME" -Value "0" -Type String -Force -ErrorAction SilentlyContinue
        }
    }

ForEach-Object {
  $phase = $_
  [pscustomobject]@{
    Id = $phase.id
    Name = $phase.name
    Scope = $phase.scope
    Status = $phase.status
    WriteAllowedNow = $false
  }
}

